#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, l, r;
    cin >> a >> b >> l >> r;
    l -= 1;
    r -= 1;

    int min_result = 26;
    for (char p = 'a'; p <= 'z'; p++) {
        for (char q = 'a' + a; q <= 'z'; q++) {
            std::string rep;
            for (int i = 0; i < a; i++) {
                rep.push_back('a' + i);
            }
            for (int i = 0; i < b; i++) {
                rep.push_back(p);
            }
            // Fill in missing characters
            for (int i = 0; i < a; i++) {
                bool f[26] = {false};
                for (int j = b; j < a + b + i; j++) {
                    f[rep[j] - 'a'] = true;
                }
                for (int j = 0; j < 26; j++) {
                    if (!f[j]) {
                        rep.push_back('a' + j);
                        break;
                    }
                }
            }
            for (int i = 0; i < b; i++) {
                rep.push_back(q);
            }

            std::vector<bool> flag(26, false);
            if (r - l + 1 >= 100000) {
                for (char ch : rep) {
                    flag[ch - 'a'] = true;
                }
            } else {
                for (int i = l; i <= r; i++) {
                    flag[rep[i % (int)rep.size()] - 'a'] = true;
                }
            }

            int ans = 0;
            for (int i = 0; i < 26; i++) {
                if (flag[i]) ans++;
            }
            min_result = std::min(ans, min_result);
        }
    }
    cout << min_result << "\n";

    return 0;
}
